js:
var reduce=window.matchMedia('(prefers-reduced-motion: reduce)').matches;
var n=root.querySelector('.t211-streak-badge-n'),medal=root.querySelector('.t211-streak-badge-medal');
var bars=root.querySelectorAll('.t211-streak-badge-w');
var raf=null;
function count(to,ms){if(reduce){n.textContent=to;return;}
 var t0=(window.performance||Date).now();
 if(raf)cancelAnimationFrame(raf);
 (function step(t){var p=Math.min(1,(t-t0)/ms),e=1-Math.pow(1-p,3);n.textContent=Math.round(to*e);if(p<1)raf=requestAnimationFrame(step);})(t0);}
function play(){
 if(!reduce){for(var i=0;i<bars.length;i++){var b=bars[i];b.style.animation='none';void b.offsetWidth;b.style.animation='';}}
 count(12,900);}
medal.addEventListener('click',play);
play();

