js:
var reduce=window.matchMedia('(prefers-reduced-motion: reduce)').matches;
var seg=root.querySelector('.t211-recur-sched-seg'),pill=root.querySelector('.t211-recur-sched-pill');
var opts=root.querySelectorAll('.t211-recur-sched-opt'),cells=root.querySelectorAll('.t211-recur-sched-date');
var per=root.querySelector('.t211-recur-sched-per'),pv=root.querySelector('.t211-recur-sched-pv');
var MO=['Jan','Feb','Mar','Apr','May','Jun','Jul','Aug','Sep','Oct','Nov','Dec'];
var modes=[{step:7,txt:'every week into VTI',pm:100*52/12},{step:14,txt:'every 2 weeks into VTI',pm:100*26/12},{step:0,txt:'every month into VTI',pm:100}];
var k=0,raf=null,shown=0;
function money(v){return '$'+Math.round(v).toString().replace(/\B(?=(\d{3})+(?!\d))/g,',');}
function dates(i){var out=[],d=new Date(),j;
 if(modes[i].step){var add=(8-d.getDay())%7;if(add===0)add=7;d.setDate(d.getDate()+add);
  for(j=0;j<3;j++){out.push(new Date(d.getTime()));d.setDate(d.getDate()+modes[i].step);}}
 else{d.setDate(1);d.setMonth(d.getMonth()+1);for(j=0;j<3;j++){out.push(new Date(d.getTime()));d.setMonth(d.getMonth()+1);}}
 return out;}
function fv(pm){var r=0.07/12,n=60;return pm*((Math.pow(1+r,n)-1)/r);}
function count(to){if(reduce){shown=to;pv.textContent=money(to);return;}
 var from=shown,t0=(window.performance||Date).now();shown=to;
 if(raf)cancelAnimationFrame(raf);
 (function step(t){var p=Math.min(1,(t-t0)/600),e=1-Math.pow(1-p,3);pv.textContent=money(from+(to-from)*e);if(p<1)raf=requestAnimationFrame(step);})(t0);}
function place(){var b=opts[k];pill.style.width=b.offsetWidth+'px';pill.style.transform='translateX('+b.offsetLeft+'px)';}
function pick(i){k=i;
 for(var j=0;j<opts.length;j++){opts[j].setAttribute('aria-pressed',j===i?'true':'false');}
 place();per.textContent=modes[i].txt;
 var ds=dates(i);
 for(var m=0;m<cells.length;m++){var c=cells[m];
  c.children[0].textContent=MO[ds[m].getMonth()];
  c.children[1].textContent=('0'+ds[m].getDate()).slice(-2);
  c.style.setProperty('--t211-recur-sched-i',m);
  if(!reduce){c.style.animation='none';void c.offsetWidth;c.style.animation='';}}
 count(fv(modes[i].pm));}
for(var i=0;i<opts.length;i++){(function(i){opts[i].addEventListener('click',function(){pick(i);});})(i);}
pick(0);
requestAnimationFrame(place);
if(window.ResizeObserver){new ResizeObserver(place).observe(seg);}
